/* @lc app=leetcode id=2846 lang=kotlin */ class Solution { fun ch(par: IntArray, dep: IntArray, cnt: Array<IntArray>, u: Int, v: Int, w: Int) = true.also { par[v] = u }.also { dep[v] = dep[u] + 1 }.also { cnt[u].copyInto(cnt[v]) }.also { cnt[v][w]++ } fun lca(up: Array<IntArray>, dep: IntArray, a0: Int, b0: Int): Int = (if (dep[a0] >= dep[b0]) a0 to b0 else b0 to a0).let { (a, b) -> (0 until 15).fold(a) { x, k -> if ((dep[a] - dep[b]) shr k and 1 == 1) up[k][x] else x }.let { a1 -> if (a1 == b) a1 else (14 downTo 0).fold(a1 to b) { (x, y), k -> if (up[k][x] != up[k][y]) up[k][x] to up[k][y] else x to y }.let { (x, _) -> up[0][x] } } } fun minOperationsQueries(n: Int, edges: Array<IntArray>, queries: Array<IntArray>): IntArray = edges.flatMap { (a, b, w) -> listOf(a to (b to w), b to (a to w)) }.groupBy({ it.first }, { it.second }).let { g -> IntArray(n) { -1 }.also { it[0] = 0 }.let { par -> IntArray(n).let { dep -> Array(n) { IntArray(27) }.let { cnt -> generateSequence(listOf(0)) { f -> f.flatMap { u -> g[u].orEmpty().filter { (v, w) -> par[v] == -1 && ch(par, dep, cnt, u, v, w) }.map { it.first } }.takeIf { it.isNotEmpty() } }.count().let { Array(15) { IntArray(n) }.also { up -> par.copyInto(up[0]) }.also { up -> (1 until 15).forEach { k -> (0 until n).forEach { v -> up[k][v] = up[k - 1][up[k - 1][v]] } } }.let { up -> queries.map { (a, b) -> lca(up, dep, a, b).let { l -> dep[a] + dep[b] - 2 * dep[l] - (1..26).maxOf { w -> cnt[a][w] + cnt[b][w] - 2 * cnt[l][w] } } }.toIntArray() } } } } } } }